#!/bin/bash
# shellcheck disable=all
# spellchecker: disable=all
set -euo pipefail; path="$(realpath "$0")";cd "$(dirname "$path")";cargo_flags=(
);echo "$(grep -m 1 -B 99999 -A 0 "^JEB" < "$path")"$'\n\n\n' > "$path"; jeb() {
cargo run "${cargo_flags[@]}" --bin jeb -- "$@" >> "$path"; exit; }; set -x



curl -sL 'https://ia802907.us.archive.org/view_archive.php?archive=/1/items/stackexchange_20250630_rev2/stackexchange_20250630_rev2/3dprinting.meta.stackexchange.com.7z&file=Posts.xml' | jeb stdin first-64 parse-xml stdout
JEB



